function widestRewriteSpread(num: number): number {
  const s = String(num);
  let hi = -Infinity, lo = Infinity;
  for (let x = 0; x <= 9; x++) {
    for (let y = 0; y <= 9; y++) {
      const t = s.split(String(x)).join(String(y));
      if (t[0] === "0") continue; // also rules out the value 0
      const v = Number(t);
      hi = Math.max(hi, v);
      lo = Math.min(lo, v);
    }
  }
  return hi - lo;
}

