function widestRewriteSpread(num: number): number {
  const s = String(num);
  const swap = (x: string, y: string) => Number(s.split(x).join(y));
  const up = [...s].find(c => c !== "9");
  const a = up === undefined ? num : swap(up, "9");
  let b = num;
  if (s[0] !== "1") b = swap(s[0], "1");
  else {
    const down = [...s].find(c => c !== "0" && c !== "1");
    if (down !== undefined) b = swap(down, "0");
  }
  return a - b;
}

